package com.procurement.compliance_engine.controller;
import com.procurement.compliance_engine.service.BidderRecommendationService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/v1/bidder/tenders") @PreAuthorize("hasRole('BIDDER')") public class BidderRecommendationController{private final BidderRecommendationService service;public BidderRecommendationController(BidderRecommendationService s){service=s;}@GetMapping("/recommended") public Map<String,Object> recommended(@RequestParam(required=false)String sector,@RequestParam(required=false)String search,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.recommended(sector,search,page,size);}}
